const int SENSOR = A0;
const int FAN = 6;                // the fan runs through the TIP120, like the motor
const float LIMIT = 30;  // turn the fan on above this

void setup() {
  Serial.begin(9600);
  pinMode(FAN, OUTPUT);
}

void loop() {
  int raw = analogRead(SENSOR);
  float volts = raw * 5.0 / 1023.0;    // 0-1023 back to 0-5 V
  float tempC = (volts - 0.5) * 100.0;  // TMP36: 0.5 V at 0 °C, plus 10 mV per °C
  Serial.println(tempC);

  if (tempC > LIMIT) {
    analogWrite(FAN, 255);
  } else {
    analogWrite(FAN, 0);
  }
  delay(200);
}
